package com.paytrace.provider;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="provider_payments") public class ProviderPaymentEntity {
 @Id private UUID id; @Column(name="provider_payment_id", unique=true,nullable=false) private String providerPaymentId; @Column(name="payment_id",unique=true,nullable=false) private UUID paymentId; @Column(nullable=false,precision=19,scale=2) private BigDecimal amount; @Column(nullable=false,length=3) private String currency; @Enumerated(EnumType.STRING) @Column(nullable=false) private ProviderState state; @Column(name="capture_count",nullable=false) private int captureCount; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt;
 protected ProviderPaymentEntity(){} public ProviderPaymentEntity(UUID paymentId, BigDecimal amount,String currency){id=UUID.randomUUID();providerPaymentId="psp_"+UUID.randomUUID().toString().replace("-","").substring(0,18);this.paymentId=paymentId;this.amount=amount;this.currency=currency;state=ProviderState.CREATED;createdAt=Instant.now();updatedAt=createdAt;}
 public String providerPaymentId(){return providerPaymentId;} public UUID paymentId(){return paymentId;} public BigDecimal amount(){return amount;} public String currency(){return currency;} public ProviderState state(){return state;} public int captureCount(){return captureCount;} public void capture(){state=ProviderState.CAPTURED;captureCount++;updatedAt=Instant.now();} public void refund(){state=ProviderState.REFUNDED;updatedAt=Instant.now();}
}
